function abbreviateProduct(left: number, right: number): string {
    let c2 = 0;
    let c5 = 0;

    for (let i = left; i <= right; i++) {
        let x = i;
        while (x % 2 === 0) {
            c2++;
            x /= 2;
        }
        while (x % 5 === 0) {
            c5++;
            x /= 5;
        }
    }

    const C = Math.min(c2, c5);
    let rem2 = C;
    let rem5 = C;

    let prod = 1;
    let over = false;
    let sumLog = 0;

    for (let i = left; i <= right; i++) {
        sumLog += Math.log10(i);

        let x = i;
        while (rem2 > 0 && x % 2 === 0) {
            x /= 2;
            rem2--;
        }
        while (rem5 > 0 && x % 5 === 0) {
            x /= 5;
            rem5--;
        }

        prod *= x;
        if (prod >= 1e10) {
            over = true;
            prod %= 1e10;
        }
    }

    if (!over) {
        return `${prod}e${C}`;
    }

    const f = sumLog - Math.floor(sumLog);
    const first5 = Math.floor(Math.pow(10, f + 4));
    const last5Str = String(prod % 100000).padStart(5, '0');

    return `${first5}...${last5Str}e${C}`;
}
