function ambiguousCoordinates(s: string): string[] {
    const digits = s.slice(1, -1);
    const ans: string[] = [];

    function getValid(S: string): string[] {
        const res: string[] = [];
        const n = S.length;

        // No decimal point
        if (n === 1 || S[0] !== '0') {
            res.push(S);
        }

        // With decimal point
        for (let j = 1; j < n; j++) {
            const left = S.slice(0, j);
            const right = S.slice(j);
            if ((left.length === 1 || left[0] !== '0') && right[right.length - 1] !== '0') {
                res.push(`${left}.${right}`);
            }
        }

        return res;
    }

    for (let i = 1; i < digits.length; i++) {
        const leftPart = digits.slice(0, i);
        const rightPart = digits.slice(i);

        const validLeft = getValid(leftPart);
        const validRight = getValid(rightPart);

        for (const l of validLeft) {
            for (const r of validRight) {
                ans.push(`(${l}, ${r})`);
            }
        }
    }

    return ans;
};
