function hitBricks(grid: number[][], hits: number[][]): number[] {
    const m = grid.length;
    const n = grid[0].length;
    const totalCells = m * n;
    const TOP = totalCells;

    const parent = new Int32Array(totalCells + 1);
    const size = new Int32Array(totalCells + 1);

    for (let i = 0; i <= totalCells; i++) {
        parent[i] = i;
        size[i] = 1;
    }
    size[TOP] = 0;

    function find(i: number): number {
        let root = i;
        while (root !== parent[root]) {
            root = parent[root];
        }
        let curr = i;
        while (curr !== root) {
            const nxt = parent[curr];
            parent[curr] = root;
            curr = nxt;
        }
        return root;
    }

    function union(i: number, j: number): void {
        const rootI = find(i);
        const rootJ = find(j);
        if (rootI !== rootJ) {
            parent[rootI] = rootJ;
            size[rootJ] += size[rootI];
        }
    }

    const hitBrick = new Uint8Array(hits.length);
    for (let k = 0; k < hits.length; k++) {
        const [r, c] = hits[k];
        if (grid[r][c] === 1) {
            hitBrick[k] = 1;
            grid[r][c] = 0;
        }
    }

    const getIndex = (r: number, c: number): number => r * n + c;

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                const idx = getIndex(r, c);
                if (r === 0) {
                    union(idx, TOP);
                }
                if (r > 0 && grid[r - 1][c] === 1) {
                    union(idx, getIndex(r - 1, c));
                }
                if (c > 0 && grid[r][c - 1] === 1) {
                    union(idx, getIndex(r, c - 1));
                }
            }
        }
    }

    const dr = [-1, 1, 0, 0];
    const dc = [0, 0, -1, 1];
    const result = new Array(hits.length).fill(0);

    for (let k = hits.length - 1; k >= 0; k--) {
        if (!hitBrick[k]) {
            continue;
        }

        const [r, c] = hits[k];
        const prevTopSize = size[find(TOP)];

        grid[r][c] = 1;
        const idx = getIndex(r, c);

        if (r === 0) {
            union(idx, TOP);
        }

        for (let d = 0; d < 4; d++) {
            const nr = r + dr[d];
            const nc = c + dc[d];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1) {
                union(idx, getIndex(nr, nc));
            }
        }

        const currTopSize = size[find(TOP)];
        result[k] = Math.max(0, currTopSize - prevTopSize - 1);
    }

    return result;
}
