function numFactoredBinaryTrees(arr: number[]): number {
    const MOD = 1000000007;
    arr.sort((a, b) => a - b);

    const dp = new Map<number, number>();
    for (const x of arr) {
        dp.set(x, 1);
    }

    for (let i = 0; i < arr.length; i++) {
        const x = arr[i];
        let count = dp.get(x)!;

        for (let j = 0; j < i; j++) {
            const y = arr[j];
            if (y * y > x) break;

            if (x % y === 0) {
                const z = x / y;
                if (dp.has(z)) {
                    const waysY = dp.get(y)!;
                    const waysZ = dp.get(z)!;
                    const ways = (waysY * waysZ) % MOD;

                    if (y === z) {
                        count = (count + ways) % MOD;
                    } else {
                        count = (count + ways * 2) % MOD;
                    }
                }
            }
        }
        dp.set(x, count);
    }

    let total = 0;
    for (const val of dp.values()) {
        total = (total + val) % MOD;
    }

    return total;
}
