function countVowelPermutation(n: number): number {
    const MOD = 1_000_000_007n;
    let a = 1n, e = 1n, i = 1n, o = 1n, u = 1n;

    for (let step = 1; step < n; step++) {
        const nextA = (e + i + u) % MOD;
        const nextE = (a + i) % MOD;
        const nextI = (e + o) % MOD;
        const nextO = i % MOD;
        const nextU = (i + o) % MOD;

        a = nextA;
        e = nextE;
        i = nextI;
        o = nextO;
        u = nextU;
    }

    return Number((a + e + i + o + u) % MOD);
}
