function clumsy(n: number): number {
    const stack: number[] = [n];
    let op = 0;

    for (let i = n - 1; i >= 1; i--) {
        if (op === 0) {
            stack.push(stack.pop()! * i);
        } else if (op === 1) {
            const prev = stack.pop()!;
            stack.push(Math.trunc(prev / i));
        } else if (op === 2) {
            stack.push(i);
        } else {
            stack.push(-i);
        }
        op = (op + 1) % 4;
    }

    return stack.reduce((acc, val) => acc + val, 0);
}
