```typescript
class MKAverage {
    private m: number;
    private k: number;
    private maxVal = 100000;
    private bitCount: Int32Array;
    private bitSum: Float64Array;
    private stream: number[];
    private head: number;

    constructor(m: number, k: number) {
        this.m = m;
        this.k = k;
        this.bitCount = new Int32Array(this.maxVal + 1);
        this.bitSum = new Float64Array(this.maxVal + 1);
        this.stream = [];
        this.head = 0;
    }

    private update(val: number, delta: number): void {
        const deltaSum = val * delta;
        for (let i = val; i <= this.maxVal; i += i & -i) {
            this.bitCount[i] += delta;
            this.bitSum[i] += deltaSum;
        }
    }

    private getKthSum(x: number): number {
        if (x === 0) return 0;
        let idx = 0;
        let currentCount = 0;
        let currentSum = 0;

        for (let step = 1 << 16; step > 0; step >>= 1) {
            if (idx + step <= this.maxVal && currentCount + this.bitCount[idx + step] < x) {
                idx += step;
                currentCount += this.bitCount[idx];
                currentSum += this.bitSum[idx];
            }
        }

        const remaining = x - currentCount;
        return currentSum + remaining * (idx + 1);
    }

    addElement(num: number): void {
        this.stream.push(num);
        this.update(num, 1);

        if (this.stream.length - this.head > this.m) {
            const oldNum = this.stream[this.head++];
            this.update(oldNum, -1);
        }
    }

    calculateMKAverage(): number {
        if (this.stream.length - this.head < this.m) {
            return -1;
        }

        const sumSmallestK = this.getKthSum(this.k);
        const sumSmallestMMinusK = this.getKthSum(this.m - this.k);
        const middleSum = sumSmallestMMinusK - sumSmallestK;

        return Math.floor(middleSum / (this.m - 2 * this.k));
    }
}
