function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    function f(s: string): number {
        let minChar = 'z';
        let count = 0;
        for (let i = 0; i < s.length; i++) {
            const c = s[i];
            if (c < minChar) {
                minChar = c;
                count = 1;
            } else if (c === minChar) {
                count++;
            }
        }
        return count;
    }

    const counts = new Int32Array(12);
    for (const w of words) {
        counts[f(w)]++;
    }

    const suffix = new Int32Array(12);
    for (let i = 10; i >= 1; i--) {
        suffix[i] = suffix[i + 1] + counts[i];
    }

    const ans: number[] = new Array(queries.length);
    for (let i = 0; i < queries.length; i++) {
        const freq = f(queries[i]);
        ans[i] = suffix[freq + 1];
    }

    return ans;
};
