function canCross(stones: number[]): boolean {
    const n = stones.length;
    if (stones[1] !== 1) {
        return false;
    }
    if (n === 2) {
        return true;
    }

    const stoneIndex = new Map<number, number>();
    for (let i = 0; i < n; i++) {
        stoneIndex.set(stones[i], i);
    }

    const dp: Set<number>[] = Array.from({ length: n }, () => new Set<number>());
    dp[1].add(1);

    for (let i = 1; i < n; i++) {
        for (const k of dp[i]) {
            for (let jump = k - 1; jump <= k + 1; jump++) {
                if (jump > 0) {
                    const nextPos = stones[i] + jump;
                    const nextIdx = stoneIndex.get(nextPos);
                    if (nextIdx !== undefined) {
                        if (nextIdx === n - 1) {
                            return true;
                        }
                        dp[nextIdx].add(jump);
                    }
                }
            }
        }
    }

    return dp[n - 1].size > 0;
}
