function maxScore(nums: number[]): number {
    const m = nums.length;
    const maxMask = 1 << m;

    function gcd(a: number, b: number): number {
        while (b !== 0) {
            const temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    const gcdTable: number[][] = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            const g = gcd(nums[i], nums[j]);
            gcdTable[i][j] = g;
            gcdTable[j][i] = g;
        }
    }

    const dp = new Int32Array(maxMask);

    for (let mask = 0; mask < maxMask; mask++) {
        let bitCount = 0;
        for (let i = 0; i < m; i++) {
            if ((mask & (1 << i)) !== 0) {
                bitCount++;
            }
        }

        if (bitCount % 2 !== 0) continue;

        const k = bitCount / 2;

        const bits: number[] = [];
        for (let i = 0; i < m; i++) {
            if ((mask & (1 << i)) !== 0) {
                bits.push(i);
            }
        }

        for (let a = 0; a < bits.length; a++) {
            for (let b = a + 1; b < bits.length; b++) {
                const i = bits[a];
                const j = bits[b];
                const prevMask = mask ^ (1 << i) ^ (1 << j);
                const score = dp[prevMask] + k * gcdTable[i][j];
                if (score > dp[mask]) {
                    dp[mask] = score;
                }
            }
        }
    }

    return dp[maxMask - 1];
}
```

