function maximumANDSum(nums: number[], numSlots: number): number {
    const n = nums.length;
    const pow3 = new Int32Array(numSlots + 1);
    pow3[0] = 1;
    for (let i = 1; i <= numSlots; i++) {
        pow3[i] = pow3[i - 1] * 3;
    }

    const maxMask = pow3[numSlots];
    const dp = new Int32Array(maxMask).fill(-1);
    const count = new Int32Array(maxMask);
    dp[0] = 0;

    let ans = 0;

    for (let mask = 0; mask < maxMask; mask++) {
        if (mask > 0) {
            count[mask] = count[(mask / 3) | 0] + (mask % 3);
        }
        const curCount = count[mask];
        if (curCount > n) continue;
        if (dp[mask] === -1) continue;

        if (curCount === n) {
            if (dp[mask] > ans) ans = dp[mask];
            continue;
        }

        const num = nums[curCount];
        for (let s = 0; s < numSlots; s++) {
            const slotCount = ((mask / pow3[s]) | 0) % 3;
            if (slotCount < 2) {
                const nextMask = mask + pow3[s];
                const val = dp[mask] + (num & (s + 1));
                if (val > dp[nextMask]) {
                    dp[nextMask] = val;
                }
            }
        }
    }

    return ans;
}
