function maxTotalFruits(fruits: number[][], startPos: number, k: number): number {
    const minSteps = (posL: number, posR: number): number => {
        if (posR <= startPos) {
            return startPos - posL;
        }
        if (posL >= startPos) {
            return posR - startPos;
        }
        return (posR - posL) + Math.min(startPos - posL, posR - startPos);
    };

    let maxFruits = 0;
    let currentFruits = 0;
    let left = 0;

    for (let right = 0; right < fruits.length; right++) {
        currentFruits += fruits[right][1];

        while (left <= right && minSteps(fruits[left][0], fruits[right][0]) > k) {
            currentFruits -= fruits[left][1];
            left++;
        }

        if (currentFruits > maxFruits) {
            maxFruits = currentFruits;
        }
    }

    return maxFruits;
};
