function eventualSafeNodes(graph: number[][]): number[] {
    const n = graph.length;
    const revGraph: number[][] = Array.from({ length: n }, () => []);
    const outDegree: number[] = new Array(n).fill(0);

    for (let u = 0; u < n; u++) {
        outDegree[u] = graph[u].length;
        for (const v of graph[u]) {
            revGraph[v].push(u);
        }
    }

    const queue: number[] = [];
    for (let i = 0; i < n; i++) {
        if (outDegree[i] === 0) {
            queue.push(i);
        }
    }

    let head = 0;
    while (head < queue.length) {
        const u = queue[head++];
        for (const v of revGraph[u]) {
            outDegree[v]--;
            if (outDegree[v] === 0) {
                queue.push(v);
            }
        }
    }

    const safeNodes: number[] = [];
    for (let i = 0; i < n; i++) {
        if (outDegree[i] === 0) {
            safeNodes.push(i);
        }
    }

    return safeNodes;
