function maxRunTime(n: number, batteries: number[]): number {
    const bigN = BigInt(n);
    let totalSum = 0n;
    for (const b of batteries) {
        totalSum += BigInt(b);
    }

    let low = 1n;
    let high = totalSum / bigN;
    let ans = 0n;

    while (low <= high) {
        const mid = (low + high) / 2n;

        let currentSum = 0n;
        for (const b of batteries) {
            const bigB = BigInt(b);
            currentSum += bigB < mid ? bigB : mid;
