function largestMagicSquare(grid: number[][]): number {
    const m = grid.length;
    const n = grid[0].length;

    const rowSum: number[][] = Array.from({ length: m }, () => new Array(n + 1).fill(0));
    const colSum: number[][] = Array.from({ length: m + 1 }, () => new Array(n).fill(0));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            rowSum[i][j + 1] = rowSum[i][j] + grid[i][j];
            colSum[i + 1][j] = colSum[i][j] + grid[i][j];
        }
    }

    for (let k = Math.min(m, n); k >= 2; k--) {
        for (let r = 0; r <= m - k; r++) {
            for (let c = 0; c <= n - k; c++) {
                let diag1 = 0;
                let diag2 = 0;
                for (let i = 0; i < k; i++) {
                    diag1 += grid[r + i][c + i];
                    diag2 += grid[r + i][c + k - 1 - i];
                }

                if (diag1 !== diag2) continue;
                const target = diag1;

                let isMagic = true;
                for (let i = 0; i < k; i++) {
                    if (rowSum[r + i][c + k] - rowSum[r + i][c] !== target) {
                        isMagic = false;
                        break;
                    }
                }
                if (!isMagic) continue;

                for (let j = 0; j < k; j++) {
                    if (colSum[r + k][c + j] - colSum[r][c + j] !== target) {
                        isMagic = false;
                        break;
                    }
                }
                if (!isMagic) continue;

                return k;
            }
        }
    }

    return 1;
}
