function maxStudents(seats: string[][]): number {
    const m = seats.length;
    const n = seats[0].length;

    // broken[r] has the c-th bit set if seats[r][c] is '#'
    const broken: number[] = new Array(m).fill(0);
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (seats[r][c] === '#') {
                broken[r] |= (1 << c);
            }
        }
    }

    // Helper to count bits
    function countBits(x: number): number {
        let count = 0;
        while (x > 0) {
            count += x & 1;
            x >>= 1;
        }
        return count;
    }

    // dp[mask] = max students up to previous row with `mask`
    let dp = new Map<number, number>();
    dp.set(0, 0);

    for (let r = 0; r < m; r++) {
        const nextDp = new Map<number, number>();
        const validMasks: number[] = [];

        for (let mask = 0; mask < (1 << n); mask++) {
            // Cannot sit in broken seats
            if ((mask & broken[r]) !== 0) continue;
            // No adjacent students in the same row
            if ((mask & (mask >> 1)) !== 0) continue;
            validMasks.push(mask);
        }

        for (const currMask of validMasks) {
            const students = countBits(currMask);
            let maxPrev = -1;

            for (const [prevMask, prevCount] of dp.entries()) {
                // Check upper-left and upper-right
                if ((currMask & (prevMask >> 1)) !== 0) continue;
                if ((currMask & (prevMask << 1)) !== 0) continue;

                if (prevCount > maxPrev) {
                    maxPrev = prevCount;
                }
            }

            if (maxPrev !== -1) {
                nextDp.set(currMask, maxPrev + students);
            }
        }

        dp = nextDp;
    }

    let ans = 0;
    for (const val of dp.values()) {
        if (val > ans) {
            ans = val;
        }
    }

    return ans;
};
