function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    flowers.sort((a, b) => a - b);

    for (let i = 0; i < n; i++) {
        if (flowers[i] > target) {
            flowers[i] = target;
        }
    }

    const pref = new Float64Array(n + 1);
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + flowers[i];
    }

    let count = 0;
    while (count < n && flowers[count] < target) {
        count++;
    }

    let maxBeauty = 0;

    for (let m = 0; m <= count; m++) {
        const costComplete = (n - m) * target - (pref[n] - pref[m]);
        if (costComplete > newFlowers) {
            continue;
        }

        if (m === 0) {
            const beauty = n * full;
            if (beauty > maxBeauty) {
                maxBeauty = beauty;
            }
            continue;
        }

        const rem = newFlowers - costComplete;

        let low = 0;
        let high = m - 1;
        while (low < high) {
            const mid = (low + high + 1) >> 1;
            const cost = (mid + 1) * flowers[mid] - pref[mid + 1];
            if (cost <= rem) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        const p = low;
        const costP = (p + 1) * flowers[p] - pref[p + 1];
        const extra = Math.floor((rem - costP) / (p + 1));
        const v = Math.min(target - 1, flowers[p] + extra);

        const beauty = (n - m) * full + v * partial;
        if (beauty > maxBeauty) {
            maxBeauty = beauty;
        }
    }

    return maxBeauty;
}
