    const n = passingFees.length;
    const INF = 1e9;
    const dp = new Int32Array((maxTime + 1) * n).fill(INF);

    dp[0] = passingFees[0];

    for (let t = 1; t <= maxTime; t++) {
        for (let i = 0; i < edges.length; i++) {
            const u = edges[i][0];
            const v = edges[i][1];
            const time = edges[i][2];

            if (t >= time) {
                const prevBase = (t - time) * n;
                const currBase = t * n;

                const costFromU = dp[prevBase + u];
                if (costFromU !== INF) {
                    const newCost = costFromU + passingFees[v];
                    if (newCost < dp[currBase + v]) {
                        dp[currBase + v] = newCost;
                    }
                }

                const costFromV = dp[prevBase + v];
                if (costFromV !== INF) {
                    const newCost = costFromV + passingFees[u];
                    if (newCost < dp[currBase + u]) {
                        dp[currBase + u] = newCost;
