    if (countIslands() !== 1) {
        return 0;
    }

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                grid[i][j] = 0;
                if (countIslands() !== 1) {
                    return 1;
                }
                grid[i][j] = 1;
            }
        }
    }

    return 2;
}
