function maxCompatibilitySum(students: number[][], mentors: number[][]): number {
    const m = students.length;
    const n = students[0].length;

    const score: number[][] = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < m; j++) {
            let s = 0;
            for (let k = 0; k < n; k++) {
                if (students[i][k] === mentors[j][k]) {
                    s++;
                }
            }
            score[i][j] = s;
        }
    }

    const dp: number[] = new Array(1 << m).fill(0);

    for (let mask = 0; mask < (1 << m); mask++) {
        let studentIdx = 0;
        for (let j = 0; j < m; j++) {
            if ((mask & (1 << j)) !== 0) {
                studentIdx++;
            }
        }

        if (studentIdx === m) continue;

        for (let j = 0; j < m; j++) {
            if ((mask & (1 << j)) === 0) {
                const nextMask = mask | (1 << j);
                dp[nextMask] = Math.max(dp[nextMask], dp[mask] + score[studentIdx][j]);
            }
        }
    }

    return dp[(1 << m) - 1];
};
