function minDays(n: number): number {
    const memo = new Map<number, number>();

    function dp(curr: number): number {
        if (curr <= 1) {
            return curr;
        }
        if (memo.has(curr)) {
            return memo.get(curr)!;
        }

        const res = 1 + Math.min(
            (curr % 2) + dp(Math.floor(curr / 2)),
            (curr % 3) + dp(Math.floor(curr / 3))
        );

        memo.set(curr, res);
        return res;
    }

    return dp(n);
}
