function maxSumTwoNoOverlap(nums: number[], firstLen: number, secondLen: number): number {
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }

    function helper(l: number, m: number): number {
        let maxL = 0;
        let ans = 0;
        for (let i = l + m; i <= n; i++) {
            const currentL = prefix[i - m] - prefix[i - m - l];
            maxL = Math.max(maxL, currentL);
            const currentM = prefix[i] - prefix[i - m];
            ans = Math.max(ans, maxL + currentM);
        }
        return ans;
    }

    return Math.max(helper(firstLen, secondLen), helper(secondLen, firstLen));
};
