function minAreaRect(points: number[][]): number {
    const pointSet = new Set<number>();
    const MULTIPLIER = 40001;

    for (let i = 0; i < points.length; i++) {
        pointSet.add(points[i][0] * MULTIPLIER + points[i][1]);
    }

    let minArea = Infinity;

    for (let i = 0; i < points.length; i++) {
        const [x1, y1] = points[i];
        for (let j = i + 1; j < points.length; j++) {
            const [x2, y2] = points[j];

            if (x1 === x2 || y1 === y2) {
                continue;
            }

            const area = Math.abs(x1 - x2) * Math.abs(y1 - y2);
            if (area >= minArea) {
                continue;
            }

            if (
                pointSet.has(x1 * MULTIPLIER + y2) &&
                pointSet.has(x2 * MULTIPLIER + y1)
            ) {
                minArea = area;
            }
        }
    }

    return minArea === Infinity ? 0 : minArea;
};
