function numOfWays(nums: number[]): number {
    const MOD = 1_000_000_007n;
    const n = nums.length;

    const comb: bigint[][] = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0n));
    for (let i = 0; i <= n; i++) {
        comb[i][0] = 1n;
        for (let j = 1; j <= i; j++) {
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
        }
    }

    function countWays(arr: number[]): bigint {
        if (arr.length <= 2) {
            return 1n;
        }

        const root = arr[0];
        const left: number[] = [];
        const right: number[] = [];

        for (let i = 1; i < arr.length; i++) {
            if (arr[i] < root) {
                left.push(arr[i]);
            } else {
                right.push(arr[i]);
            }
        }

        const leftWays = countWays(left);
        const rightWays = countWays(right);
        const ways = (comb[left.length + right.length][left.length] * leftWays) % MOD;
        return (ways * rightWays) % MOD;
    }

    const totalWays = countWays(nums);
    return Number((totalWays - 1n + MOD) % MOD);
};
