function minDays(bloomDay: number[], m: number, k: number): number {
    if (m * k > bloomDay.length) {
        return -1;
    }

    let left = 1;
    let right = 0;
    for (const day of bloomDay) {
        if (day > right) {
            right = day;
        }
    }

    const canMake = (days: number): boolean => {
        let bouquets = 0;
        let consecutive = 0;
        for (const day of bloomDay) {
            if (day <= days) {
                consecutive++;
                if (consecutive === k) {
                    bouquets++;
                    consecutive = 0;
                }
            } else {
                consecutive = 0;
            }
        }
        return bouquets >= m;
    };

    let ans = -1;
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (canMake(mid)) {
            ans = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    return ans;
};
