function maxSizeSlices(slices: number[]): number {
    const totalSlices = slices.length;
    const n = Math.floor(totalSlices / 3);

    function solveLinear(arr: number[], k: number): number {
        const m = arr.length;
        // dp[i][j]: max sum picking j elements from the first i elements of arr
        const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(k + 1).fill(0));

        for (let i = 1; i <= m; i++) {
            for (let j = 1; j <= k; j++) {
                const notPick = dp[i - 1][j];
                const pick = arr[i - 1] + (i >= 2 ? dp[i - 2][j - 1] : 0);
                dp[i][j] = Math.max(notPick, pick);
            }
        }

        return dp[m][k];
    }

    const case1 = solveLinear(slices.slice(0, totalSlices - 1), n);
    const case2 = solveLinear(slices.slice(1), n);

    return Math.max(case1, case2);
};
