function friendRequests(n: number, restrictions: number[][], requests: number[][]): boolean[] {
    const parent = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        parent[i] = i;
    }

    function find(i: number): number {
        let root = i;
        while (root !== parent[root]) {
            root = parent[root];
        }
        let curr = i;
        while (curr !== root) {
            const next = parent[curr];
            parent[curr] = root;
            curr = next;
        }
        return root;
    }

    const ans: boolean[] = [];

    for (const [u, v] of requests) {
        const rootU = find(u);
        const rootV = find(v);

        if (rootU === rootV) {
            ans.push(true);
            continue;
        }

        let canUnion = true;
        for (const [x, y] of restrictions) {
            const rootX = find(x);
            const rootY = find(y);

            if (
                (rootX === rootU && rootY === rootV) ||
                (rootX === rootV && rootY === rootU)
            ) {
                canUnion = false;
                break;
            }
        }

        if (canUnion) {
            parent[rootU] = rootV;
            ans.push(true);
        } else {
            ans.push(false);
        }
    }

    return ans;
}
