function minSessions(tasks: number[], sessionTime: number): number {
    const n = tasks.length;
    const numStates = 1 << n;

    const sessions = new Int32Array(numStates).fill(Infinity);
    const time = new Int32Array(numStates).fill(Infinity);

    sessions[0] = 1;
    time[0] = 0;

    for (let mask = 0; mask < numStates; mask++) {
        const currentSessions = sessions[mask];
        const currentTime = time[mask];

        for (let i = 0; i < n; i++) {
            if ((mask & (1 << i)) === 0) {
                const nextMask = mask | (1 << i);
                let nextSessions = currentSessions;
                let nextTime = currentTime + tasks[i];

                if (nextTime > sessionTime) {
                    nextSessions++;
                    nextTime = tasks[i];
                }

                if (
                    nextSessions < sessions[nextMask] ||
                    (nextSessions === sessions[nextMask] && nextTime < time[nextMask])
                ) {
                    sessions[nextMask] = nextSessions;
                    time[nextMask] = nextTime;
                }
            }
        }
    }

    return sessions[numStates - 1];
}
