    const n = nums.length;
    const res: number[] = new Array(n).fill(-1);
    const stack: number[] = [];

    for (let i = 2 * n - 1; i >= 0; i--) {
        const val = nums[i % n];
        while (stack.length > 0 && stack[stack.length - 1] <= val) {
            stack.pop();
        }
        if (i < n && stack.length > 0) {
            res[i] = stack[stack.length - 1];
