function isScramble(s1: string, s2: string): boolean {
    const n = s1.length;
    const memo: Int8Array[][] = Array.from({ length: n + 1 }, () =>
        Array.from({ length: n }, () => new Int8Array(n).fill(-1))
    );

    function helper(i1: number, i2: number, len: number): boolean {
        if (memo[len][i1][i2] !== -1) {
            return memo[len][i1][i2] === 1;
        }

        let equal = true;
        for (let i = 0; i < len; i++) {
            if (s1.charCodeAt(i1 + i) !== s2.charCodeAt(i2 + i)) {
                equal = false;
                break;
            }
        }
        if (equal) {
            memo[len][i1][i2] = 1;
            return true;
        }

        const count = new Int32Array(26);
        for (let i = 0; i < len; i++) {
            count[s1.charCodeAt(i1 + i) - 97]++;
            count[s2.charCodeAt(i2 + i) - 97]--;
        }
        for (let i = 0; i < 26; i++) {
            if (count[i] !== 0) {
                memo[len][i1][i2] = 0;
                return false;
            }
        }

        for (let k = 1; k < len; k++) {
            if (
                (helper(i1, i2, k) && helper(i1 + k, i2 + k, len - k)) ||
                (helper(i1, i2 + len - k, k) && helper(i1 + k, i2, len - k))
            ) {
                memo[len][i1][i2] = 1;
                return true;
            }
        }

        memo[len][i1][i2] = 0;
        return false;
    }

    return helper(0, 0, n);
};
