```typescript
class Heap {
    data: number[] = [];
    compare: (a: number, b: number) => number;

    constructor(compare: (a: number, b: number) => number) {
        this.compare = compare;
    }

    push(val: number): void {
        this.data.push(val);
        this.up(this.data.length - 1);
    }

    pop(): number | undefined {
        if (this.data.length === 0) return undefined;
        const top = this.data[0];
        const bottom = this.data.pop()!;
        if (this.data.length > 0) {
            this.data[0] = bottom;
            this.down(0);
        }
        return top;
    }

    peek(): number {
        return this.data[0];
    }

    size(): number {
        return this.data.length;
    }

    private up(i: number): void {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this.compare(this.data[i], this.data[p]) < 0) {
                const tmp = this.data[i];
                this.data[i] = this.data[p];
                this.data[p] = tmp;
                i = p;
            } else {
                break;
            }
        }
    }

    private down(i: number): void {
        const len = this.data.length;
        while ((i << 1) + 1 < len) {
            const left = (i << 1) + 1;
            const right = left + 1;
            let best = i;
            if (this.compare(this.data[left], this.data[best]) < 0) {
                best = left;
            }
            if (right < len && this.compare(this.data[right], this.data[best]) < 0) {
                best = right;
            }
            if (best !== i) {
                const tmp = this.data[i];
                this.data[i] = this.data[best];
                this.data[best] = tmp;
                i = best;
            } else {
                break;
            }
        }
    }
}

function medianSlidingWindow(nums: number[], k: number): number[] {
    const small = new Heap((a, b) => b - a); // max-heap
    const large = new Heap((a, b) => a - b); // min-heap
    const delayed = new Map<number, number>();

    let smallSize = 0;
    let largeSize = 0;

    const prune = (heap: Heap): void => {
        while (heap.size() > 0) {
            const top = heap.peek();
            const count = delayed.get(top);
            if (count && count > 0) {
                if (count === 1) {
                    delayed.delete(top);
                } else {
                    delayed.set(top, count - 1);
                }
                heap.pop();
            } else {
                break;
            }
        }
    };

    const makeBalance = (): void => {
        const targetSmallSize = Math.floor((k + 1) / 2);
        while (smallSize > targetSmallSize) {
            large.push(small.pop()!);
            smallSize--;
            largeSize++;
            prune(small);
        }
        while (smallSize < targetSmallSize) {
            small.push(large.pop()!);
            smallSize++;
            largeSize--;
            prune(large);
        }
    };

    const insert = (num: number): void => {
        if (smallSize === 0 || num <= small.peek()) {
            small.push(num);
            smallSize++;
        } else {
            large.push(num);
            largeSize++;
        }
        makeBalance();
    };

    const erase = (num: number): void => {
        delayed.set(num, (delayed.get(num) || 0) + 1);
        if (num <= small.peek()) {
            smallSize--;
            if (num === small.peek()) {
                prune(small);
            }
        } else {
            largeSize--;
            if (num === large.peek()) {
                prune(large);
            }
        }
        makeBalance();
    };

    const getMedian = (): number => {
        if (k % 2 === 1) {
            return small.peek();
        } else {
            return (small.peek() + large.peek()) / 2;
        }
    };

    for (let i = 0; i < k; i++) {
        insert(nums[i]);
    }

    const result: number[] = [getMedian()];

    for (let i = k; i < nums.length; i++) {
        insert(nums[i]);
        erase(nums[i - k]);
        result.push(getMedian());
    }

    return result;
}
