    k = k % total;

    const result: number[][] = Array.from({ length: m }, () => new Array(n));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const newIndex = (i * n + j + k) % total;
            const newRow = Math.floor(newIndex / n);
            const newCol = newIndex % n;
            result[newRow][newCol] = grid[i][j];
        }
    }

    return result;
};
