function splitArray(nums: number[], k: number): number {
    let left = 0;
    let right = 0;

    for (const num of nums) {
        if (num > left) {
            left = num;
        }
        right += num;
    }

    const canSplit = (maxSum: number): boolean => {
        let count = 1;
        let currentSum = 0;

        for (const num of nums) {
            if (currentSum + num > maxSum) {
                count++;
                currentSum = num;
            } else {
                currentSum += num;
            }
        }

        return count <= k;
    };

    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (canSplit(mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }

    return left;
};
