function minStickers(stickers: string[], target: string): number {
    const n = target.length;
    const stickerCounts: number[][] = [];

    for (const sticker of stickers) {
        const count = new Array(26).fill(0);
        for (let i = 0; i < sticker.length; i++) {
            count[sticker.charCodeAt(i) - 97]++;
        }
        stickerCounts.push(count);
    }

    const maxMask = 1 << n;
    const dist = new Int32Array(maxMask).fill(-1);
    const startMask = maxMask - 1;

    const queue = new Int32Array(maxMask);
    let head = 0;
    let tail = 0;

    queue[tail++] = startMask;
    dist[startMask] = 0;

    while (head < tail) {
        const mask = queue[head++];

        if (mask === 0) {
            return dist[0];
        }

        // Find the first uncovered character
        let firstBit = 0;
        for (let i = 0; i < n; i++) {
            if ((mask & (1 << i)) !== 0) {
                firstBit = i;
                break;
            }
        }

        const targetChar = target.charCodeAt(firstBit) - 97;

        for (const sticker of stickerCounts) {
            // Pruning: only consider stickers containing target[firstBit]
            if (sticker[targetChar] === 0) continue;

            let nextMask = mask;
            const available = sticker.slice();

            for (let i = 0; i < n; i++) {
                if ((nextMask & (1 << i)) !== 0) {
                    const c = target.charCodeAt(i) - 97;
                    if (available[c] > 0) {
                        available[c]--;
                        nextMask ^= 1 << i;
                    }
                }
            }

            if (dist[nextMask] === -1) {
                dist[nextMask] = dist[mask] + 1;
                queue[tail++] = nextMask;
            }
        }
    }

    return -1;
}
