function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const size = 3 * n;
    const matrix: Uint8Array = new Uint8Array(size * size);

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const char = grid[r][c];
            if (char === '/') {
                matrix[r * 3 * size + (c * 3 + 2)] = 1;
                matrix[(r * 3 + 1) * size + (c * 3 + 1)] = 1;
                matrix[(r * 3 + 2) * size + (c * 3)] = 1;
            } else if (char === '\\') {
                matrix[r * 3 * size + (c * 3)] = 1;
                matrix[(r * 3 + 1) * size + (c * 3 + 1)] = 1;
                matrix[(r * 3 + 2) * size + (c * 3 + 2)] = 1;
            }
        }
    }

    let regions = 0;
    const queue: number[] = [];
    const dirs = [-1, 0, 1, 0, -1];

    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            const idx = i * size + j;
            if (matrix[idx] === 0) {
                regions++;
                matrix[idx] = 1;
                queue.push(idx);

                let head = 0;
                while (head < queue.length) {
                    const curr = queue[head++];
                    const r = Math.floor(curr / size);
                    const c = curr % size;

                    for (let d = 0; d < 4; d++) {
                        const nr = r + dirs[d];
                        const nc = c + dirs[d + 1];

                        if (nr >= 0 && nr < size && nc >= 0 && nc < size) {
                            const nidx = nr * size + nc;
                            if (matrix[nidx] === 0) {
                                matrix[nidx] = 1;
                                queue.push(nidx);
                            }
                        }
                    }
                }
                queue.length = 0;
            }
        }
    }

    return regions;
};
