```typescript
function earliestAndLatest(n: number, firstPlayer: number, secondPlayer: number): number[] {
    const memo: Map<number, [number, number]> = new Map();

    function encode(k: number, p1: number, p2: number): number {
        return (k << 12) | (p1 << 6) | p2;
    }

    function solve(k: number, p1: number, p2: number): [number, number] {
        if (p1 + p2 === k + 1) {
            return [1, 1];
        }

        const key = encode(k, p1, p2);
        if (memo.has(key)) {
            return memo.get(key)!;
        }

        // reachable will store all possible (c1, c2) pairs,
        // where c1 = count of winners < p1, c2 = count of winners < p2.
        // Pack (c1, c2) as (c1 << 6) | c2 into a Set.
        let reachable = new Set<number>();

        // Handle the middle player if k is odd
        let initC1 = 0;
        let initC2 = 0;
        if (k % 2 === 1) {
            const mid = Math.floor((k + 1) / 2);
            if (mid < p1) initC1++;
            if (mid < p2) initC2++;
        }
        reachable.add((initC1 << 6) | initC2);

        const m = Math.floor(k / 2);
        for (let i = 1; i <= m; i++) {
            const A = i;
            const B = k - i + 1;

            const nextReachable = new Set<number>();

            // Determine possible winners for this match
            let possibleWinners: number[];
            if (A === p1 || B === p1) {
                possibleWinners = [p1];
            } else if (A === p2 || B === p2) {
                possibleWinners = [p2];
            } else {
                possibleWinners = [A, B];
            }

            for (const state of reachable) {
                const c1 = state >> 6;
                const c2 = state & 63;

                for (const w of possibleWinners) {
                    const nextC1 = c1 + (w < p1 ? 1 : 0);
                    const nextC2 = c2 + (w < p2 ? 1 : 0);
                    nextReachable.add((nextC1 << 6) | nextC2);
                }
            }

            reachable = nextReachable;
        }

        const nextK = Math.floor((k + 1) / 2);
        let minR = Infinity;
        let maxR = -Infinity;

        for (const state of reachable) {
            const c1 = state >> 6;
            const c2 = state & 63;
            const nextP1 = c1 + 1;
            const nextP2 = c2 + 1;

            const [subMin, subMax] = solve(nextK, nextP1, nextP2);
            if (subMin + 1 < minR) minR = subMin + 1;
            if (subMax + 1 > maxR) maxR = subMax + 1;
        }

        const res: [number, number] = [minR, maxR];
        memo.set(key, res);
        return res;
    }

    return solve(n, firstPlayer, secondPlayer);
}
