function getCoprimes(nums: number[], edges: number[][]): number[] {
    const n = nums.length;

    // Helper for gcd
    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    };

    // Precompute coprime numbers for each value in [1, 50]
    const coprimesOf: number[][] = Array.from({ length: 51 }, () => []);
    for (let i = 1; i <= 50; i++) {
        for (let j = 1; j <= 50; j++) {
            if (gcd(i, j) === 1) {
                coprimesOf[i].push(j);
            }
        }
    }

    // Build adjacency list
    const adj: number[][] = Array.from({ length: n }, () => []);
    for (let i = 0; i < edges.length; i++) {
        const u = edges[i][0];
        const v = edges[i][1];
        adj[u].push(v);
        adj[v].push(u);
    }

    const ans: number[] = new Array(n).fill(-1);
    const depth = new Int32Array(n);
    const parent = new Int32Array(n).fill(-1);
    const curEdgeIndex = new Int32Array(n);

    // Stacks for each value 1..50
    const valStack: number[][] = Array.from({ length: 51 }, () => []);

    // Function to process a node
    const processNode = (u: number) => {
        let maxDepth = -1;
        let bestNode = -1;
        const coprimes = coprimesOf[nums[u]];
        for (let i = 0; i < coprimes.length; i++) {
            const v = coprimes[i];
            const s = valStack[v];
            if (s.length > 0) {
                const anc = s[s.length - 1];
                if (depth[anc] > maxDepth) {
                    maxDepth = depth[anc];
                    bestNode = anc;
                }
            }
        }
        ans[u] = bestNode;
        valStack[nums[u]].push(u);
    };

    // Iterative DFS to avoid call stack overflow
    const stack: number[] = [0];
    depth[0] = 0;
    processNode(0);

    while (stack.length > 0) {
        const u = stack[stack.length - 1];
        const neighbors = adj[u];

        if (curEdgeIndex[u] < neighbors.length) {
            const v = neighbors[curEdgeIndex[u]++];
            if (v !== parent[u]) {
                parent[v] = u;
                depth[v] = depth[u] + 1;
                processNode(v);
                stack.push(v);
            }
        } else {
            valStack[nums[u]].pop();
            stack.pop();
        }
    }

    return ans;
}
