function spiralMatrixIII(rows: number, cols: number, rStart: number, cStart: number): number[][] {
    const res: number[][] = [[rStart, cStart]];
    const total = rows * cols;
    if (total === 1) return res;

    const dr = [0, 1, 0, -1];
    const dc = [1, 0, -1, 0];
    let r = rStart;
    let c = cStart;
    let step = 1;
    let d = 0;

