function isSolvable(words: string[], result: string): boolean {
    const maxLen = result.length;
    for (const w of words) {
        if (w.length > maxLen) return false;
    }

    const cannotBeZero = new Uint8Array(26);
    for (const w of words) {
        if (w.length > 1) {
            cannotBeZero[w.charCodeAt(0) - 65] = 1;
        }
    }
    if (result.length > 1) {
        cannotBeZero[result.charCodeAt(0) - 65] = 1;
    }

    const charToDigit = new Int8Array(26).fill(-1);
    const digitUsed = new Uint8Array(10);

    function backtrack(col: number, wordIdx: number, sum: number): boolean {
        if (col === maxLen) {
            return sum === 0;
        }

        if (wordIdx < words.length) {
            const w = words[wordIdx];
            if (col >= w.length) {
                return backtrack(col, wordIdx + 1, sum);
            }

            const c = w.charCodeAt(w.length - 1 - col) - 65;
            if (charToDigit[c] !== -1) {
                return backtrack(col, wordIdx + 1, sum + charToDigit[c]);
            }

            const startDigit = cannotBeZero[c] ? 1 : 0;
            for (let d = startDigit; d <= 9; d++) {
                if (!digitUsed[d]) {
                    digitUsed[d] = 1;
                    charToDigit[c] = d;
                    if (backtrack(col, wordIdx + 1, sum + d)) {
                        return true;
                    }
                    charToDigit[c] = -1;
                    digitUsed[d] = 0;
                }
            }
            return false;
        }

        const c = result.charCodeAt(result.length - 1 - col) - 65;
        const expectedDigit = sum % 10;
        const nextCarry = Math.floor(sum / 10);

        if (charToDigit[c] !== -1) {
            if (charToDigit[c] === expectedDigit) {
                return backtrack(col + 1, 0, nextCarry);
            }
            return false;
        }

        if (expectedDigit === 0 && cannotBeZero[c]) {
            return false;
        }

        if (!digitUsed[expectedDigit]) {
            digitUsed[expectedDigit] = 1;
            charToDigit[c] = expectedDigit;
            if (backtrack(col + 1, 0, nextCarry)) {
                return true;
            }
            charToDigit[c] = -1;
            digitUsed[expectedDigit] = 0;
        }

        return false;
    }

    return backtrack(0, 0, 0);
}
