function validateBinaryTreeNodes(n: number, leftChild: number[], rightChild: number[]): boolean {
    const inDegree = new Int32Array(n);

    for (let i = 0; i < n; i++) {
        const left = leftChild[i];
        if (left !== -1) {
            inDegree[left]++;
            if (inDegree[left] > 1) return false;
        }
        const right = rightChild[i];
        if (right !== -1) {
            inDegree[right]++;
            if (inDegree[right] > 1) return false;
        }
    }

    let root = -1;
    for (let i = 0; i < n; i++) {
        if (inDegree[i] === 0) {
            if (root !== -1) return false;
            root = i;
        }
    }

    if (root === -1) return false;

    const visited = new Uint8Array(n);
    const queue = [root];
    visited[root] = 1;
    let count = 0;

    while (queue.length > 0) {
        const curr = queue.pop()!;
        count++;

        const left = leftChild[curr];
        if (left !== -1) {
            if (visited[left]) return false;
            visited[left] = 1;
            queue.push(left);
        }

        const right = rightChild[curr];
        if (right !== -1) {
            if (visited[right]) return false;
            visited[right] = 1;
            queue.push(right);
        }
    }

    return count === n;
};
