function ladderLength(beginWord: string, endWord: string, wordList: string[]): number {
    const dict = new Set<string>(wordList);
    if (!dict.has(endWord)) {
        return 0;
    }

    let beginSet = new Set<string>([beginWord]);
    let endSet = new Set<string>([endWord]);
    const visited = new Set<string>([beginWord, endWord]);
    let step = 1;

    const alphabet = 'abcdefghijklmnopqrstuvwxyz';

    while (beginSet.size > 0 && endSet.size > 0) {
        if (beginSet.size > endSet.size) {
            const temp = beginSet;
            beginSet = endSet;
            endSet = temp;
        }

        const nextSet = new Set<string>();

        for (const word of beginSet) {
            const chars = word.split('');
            for (let i = 0; i < chars.length; i++) {
                const originalChar = chars[i];
                for (let j = 0; j < 26; j++) {
                    const char = alphabet[j];
                    if (char === originalChar) continue;
                    chars[i] = char;
                    const nextWord = chars.join('');

                    if (endSet.has(nextWord)) {
                        return step + 1;
                    }

                    if (dict.has(nextWord) && !visited.has(nextWord)) {
                        visited.add(nextWord);
                        nextSet.add(nextWord);
                    }
                }
                chars[i] = originalChar;
            }
        }

        beginSet = nextSet;
        step++;
    }

    return 0;
};
